import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { format } from "prettier";
import { parseDocument } from "yaml";
import { materializeToolSchemas } from "./mcp-schema-materializer.mjs";

const repositoryRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
);
const bundleRoot = path.join(
  repositoryRoot,
  "Documentation/ODPMarketStewardBundle",
);
const manifestPath = path.join(bundleRoot, "bundle.yaml");
const manifestYaml = await readFile(manifestPath, "utf8");
const manifest = parseStrict(manifestYaml, "bundle.yaml");
if (!Array.isArray(manifest.artifacts)) {
  throw new Error("bundle.yaml has no artifacts array.");
}
const runtimeArtifacts = manifest.artifacts.filter(
  (artifact) => artifact.requiredAtRuntime === true,
);
const files = {};
const parsedFiles = {};
for (const artifact of runtimeArtifacts) {
  assertSafePath(artifact.path);
  const content = await readFile(path.join(bundleRoot, artifact.path), "utf8");
  parsedFiles[artifact.path] = parseStrict(content, artifact.path);
  const observed = createHash("sha256").update(content).digest("hex");
  if (observed !== artifact.sha256) {
    throw new Error(
      `${artifact.path}: expected SHA-256 ${artifact.sha256}, observed ${observed}.`,
    );
  }
  files[artifact.path] = content;
}
const expectedOrder = [
  "bundle.yaml",
  ...runtimeArtifacts.map((artifact) => artifact.path),
];
if (
  JSON.stringify(manifest.runtimePolicy?.loadOrder) !==
  JSON.stringify(expectedOrder)
) {
  throw new Error(
    "Runtime loadOrder does not match runtime artifact declaration order.",
  );
}

const output = await format(
  `// Generated by scripts/compile-governed-bundle.mjs. Do not edit manually.
import type { EmbeddedGovernedBundle } from "@odp-market-steward/contract-runtime";

export const governedBundle: EmbeddedGovernedBundle = {
  manifestPath: "bundle.yaml",
  manifestYaml: ${JSON.stringify(manifestYaml)},
  files: ${JSON.stringify(files, null, 2)},
};
`,
  { parser: "typescript" },
);
await writeFile(
  path.join(repositoryRoot, "generated/governed-bundle.ts"),
  output,
  "utf8",
);

const applicationContractPath = "application/mcp-application.yaml";
const applicationContract = parsedFiles[applicationContractPath];
if (applicationContract === undefined) {
  throw new Error(
    `${applicationContractPath}: required runtime artifact missing.`,
  );
}
const toolSchemas = materializeToolSchemas(applicationContract);
const schemaOutput = await format(
  `// Generated by scripts/compile-governed-bundle.mjs. Do not edit manually.
export const MCP_TOOL_SCHEMAS = ${JSON.stringify(toolSchemas, null, 2)} as const;

export type McpToolName = keyof typeof MCP_TOOL_SCHEMAS;
export type McpToolSchemaPair = (typeof MCP_TOOL_SCHEMAS)[McpToolName];
`,
  { parser: "typescript" },
);
await writeFile(
  path.join(repositoryRoot, "generated/standalone-tool-schemas.ts"),
  schemaOutput,
  "utf8",
);
console.log(
  JSON.stringify({
    status: "PASS",
    runtimeArtifacts: runtimeArtifacts.length,
    bundleVersion: manifest.metadata?.version,
    tools: Object.keys(toolSchemas).length,
    standaloneSchemas: Object.keys(toolSchemas).length * 2,
  }),
);

function parseStrict(source, artifactPath) {
  const document = parseDocument(source, {
    prettyErrors: true,
    strict: true,
    uniqueKeys: true,
  });
  if (document.errors.length > 0) {
    throw new Error(
      `${artifactPath}: ${document.errors.map((error) => error.message).join("; ")}`,
    );
  }
  return document.toJS({ maxAliasCount: 0 });
}

function assertSafePath(artifactPath) {
  const segments = artifactPath.split("/");
  if (
    artifactPath.startsWith("/") ||
    artifactPath.includes("\\") ||
    segments.some(
      (segment) => segment === "" || segment === "." || segment === "..",
    )
  ) {
    throw new Error(`Unsafe bundle-relative path: ${artifactPath}`);
  }
}
